/* One active reflection, with letter geometry cached on entry. */
(()=>{
const title=document.querySelector('#accueil .hero-title'),letters=[...title.querySelectorAll('.hero-letter')],reduced=matchMedia('(prefers-reduced-motion:reduce)'),fine=matchMedia('(hover:hover) and (pointer:fine)');letters.forEach(l=>l.dataset.metalLetter=l.textContent);
const surname=title.querySelector('.outline-name');for(let i=0;i<3;i++){const spark=document.createElement('i');spark.className='name-metal-spark';spark.setAttribute('aria-hidden','true');surname.append(spark)}
let frame=0,point=null,active=null,rects=new Map();function cache(){rects=new Map(letters.map(l=>[l,(()=>{const r=l.getBoundingClientRect();return {left:r.left,top:r.top,sx:l.offsetWidth/r.width,sy:l.offsetHeight/r.height}})()]))}function clear(){if(active)active.style.setProperty('--metal-reflection','0');active=null;point=null;cancelAnimationFrame(frame);frame=0}
function reflect(){frame=0;if(!point||reduced.matches)return;const letter=point.target.closest('.hero-letter');if(active!==letter){if(active)active.style.setProperty('--metal-reflection','0');active=letter}const r=rects.get(letter);if(!r)return;letter.style.setProperty('--metal-x',`${(point.clientX-r.left)*r.sx}px`);letter.style.setProperty('--metal-y',`${(point.clientY-r.top)*r.sy}px`);letter.style.setProperty('--metal-reflection','1')}
if(fine.matches){title.addEventListener('pointerenter',cache,{passive:true});title.addEventListener('transitionend',cache);title.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||reduced.matches)return;point=e;if(!frame)frame=requestAnimationFrame(reflect)},{passive:true});title.addEventListener('pointerleave',clear)}addEventListener('resize',()=>{clear();rects.clear()},{passive:true});addEventListener('scroll',clear,{passive:true});reduced.addEventListener('change',clear);
})();
